export type LadderArt = {
  level: number;
  name: string;
  board: string;
  /** Colour groups (what a waiter fetches), each 1 to 4 flat tones (keys of LADDER_TONES), light to dark. */
  groups: readonly (readonly (keyof typeof LADDER_TONES)[])[];
  /** Each group's waiter colour (the tone most of its cubes have). */
  reps: readonly (keyof typeof LADDER_TONES)[];
  /** 28 rows of 28 characters: `.` board, `#` a cube of the picture's dark outline, else the index (0-9, a-z) into the groups' tones in order. */
  rows: readonly string[];
};

